  if (weapon.id === 'beam') { for (let i = 0; i < count; i++) { const a = baseAngle + (i - (count - 1) / 2) * .16; game.projectiles.push({ type: 'beam', x: game.player.x, y: game.player.y, angle: a, life: weapon.evolution ? .3 : .15, damage: stats.damage, color: WEAPONS[weapon.id].color, evolved: weapon.evolution }); } return; }
