  for (let i = 0; i < count; i++) { const spread = weapon.id === 'flak' ? (i - (count - 1) / 2) * .16 : (i - (count - 1) / 2) * .06; const a = baseAngle + spread; game.projectiles.push({ type: weapon.id, x: game.player.x, y: game.player.y, vx: Math.cos(a) * stats.speed, vy: Math.sin(a) * stats.speed, life: weapon.id === 'missile' ? 5 : 2.5, damage: stats.damage, pierce: stats.pierce, color: WEAPONS[weapon.id].color, homing: weapon.id === 'drone', evolved: weapon.evolution }); }
