function drawLongBeams() { const range = Math.hypot(innerWidth, innerHeight) * 2; for (const shot of game.projectiles) { if (shot.type !== 'beam') continue; ctx.save(); ctx.globalAlpha = .42; ctx.strokeStyle = shot.evolved ? '#ffffff' : shot.color; ctx.shadowColor = shot.evolved ? '#f2ee9f' : shot.color; ctx.shadowBlur = shot.evolved ? 22 : 10; ctx.lineWidth = shot.evolved ? 5 : 2; ctx.beginPath(); ctx.moveTo(shot.x, shot.y); ctx.lineTo(shot.x + Math.cos(shot.angle) * range, shot.y + Math.sin(shot.angle) * range); ctx.stroke(); ctx.restore(); } }
function drawExplosions() { for (const explosion of game.explosions) { const progress = explosion.life / explosion.max; ctx.save(); ctx.globalAlpha = progress; ctx.strokeStyle = explosion.color; ctx.shadowColor = explosion.color; ctx.shadowBlur = 18; ctx.lineWidth = 4; ctx.beginPath(); ctx.arc(explosion.x, explosion.y, explosion.radius * (1 - progress * .35), 0, TAU); ctx.stroke(); ctx.restore(); } }
function drawShard(shard) { ctx.save(); ctx.translate(shard.x, shard.y); ctx.rotate(shard.spin); ctx.fillStyle = shard.color; ctx.shadowColor = shard.color; ctx.shadowBlur = 8; ctx.beginPath(); ctx.moveTo(0, -6); ctx.lineTo(4, 0); ctx.lineTo(0, 6); ctx.lineTo(-4, 0); ctx.closePath(); ctx.fill(); ctx.restore(); }
function drawEffects() { for (const particle of game.particles) { ctx.globalAlpha = particle.life / particle.max; ctx.fillStyle = particle.color; ctx.fillRect(particle.x, particle.y, particle.size, particle.size); } ctx.globalAlpha = 1; for (const text of game.floating) { ctx.globalAlpha = text.life; ctx.fillStyle = text.color; ctx.font = '700 12px Barlow Condensed'; ctx.fillText(text.text, text.x, text.y); } ctx.globalAlpha = 1; }
function endRun() { game.running = false; submitScore(); document.getElementById('result-time').textContent = document.getElementById('time-display').textContent; document.getElementById('result-kills').textContent = game.kills; document.getElementById('result-shards').textContent = game.shards; document.getElementById('gameover-modal').classList.remove('hidden'); }
function showVictory() { if (game.victory) return; submitScore(); game.victory = true; game.paused = true; document.getElementById('victory-time').textContent = document.getElementById('time-display').textContent; document.getElementById('victory-kills').textContent = game.kills; document.getElementById('victory-shards').textContent = game.shards; document.getElementById('victory-modal').classList.remove('hidden'); }
function finishRun() { game.running = false; game.paused = false; document.getElementById('victory-modal').classList.add('hidden'); document.getElementById('game-screen').classList.remove('active'); document.getElementById('start-screen').classList.add('active'); }
function continueEndless() { game.endless = true; game.victory = false; game.paused = false; document.getElementById('victory-modal').classList.add('hidden'); }
function togglePause() { if (!game || !game.running || !document.getElementById('level-modal').classList.contains('hidden')) return; game.paused = !game.paused; const pauseModal = document.getElementById('pause-modal'); pauseModal.classList.toggle('hidden', !game.paused); if (game.paused) document.getElementById('god-mode-toggle').checked = game.godMode; }

renderShipSelect(); renderSelectedShip(); setupCanvas(); addEventListener('resize', setupCanvas); addEventListener('keydown', event => { keys.add(event.key.toLowerCase()); if (event.key === 'Escape') togglePause(); }); addEventListener('keyup', event => keys.delete(event.key.toLowerCase()));
document.getElementById('launch-btn').addEventListener('click', createRun); document.getElementById('choose-ship-btn').addEventListener('click', () => document.getElementById('ship-select-modal').classList.remove('hidden')); document.getElementById('close-ship-select').addEventListener('click', () => document.getElementById('ship-select-modal').classList.add('hidden')); document.getElementById('settings-btn').addEventListener('click', () => { document.getElementById('volume-slider').value = audioSettings.volume; document.getElementById('volume-value').textContent = `${audioSettings.volume}%`; document.getElementById('mute-toggle').checked = audioSettings.muted; document.getElementById('settings-modal').classList.remove('hidden'); }); document.getElementById('close-settings').addEventListener('click', () => document.getElementById('settings-modal').classList.add('hidden')); document.getElementById('volume-slider').addEventListener('input', event => { audioSettings.volume = Number(event.target.value); localStorage.setItem('void-volume', audioSettings.volume); document.getElementById('volume-value').textContent = `${audioSettings.volume}%`; unlockAudio(); playSound('level'); }); document.getElementById('mute-toggle').addEventListener('change', event => { audioSettings.muted = event.target.checked; localStorage.setItem('void-muted', audioSettings.muted); }); document.getElementById('name-form').addEventListener('submit', event => { event.preventDefault(); submitNamedScore(document.getElementById('pilot-name').value.trim()); document.getElementById('name-modal').classList.add('hidden'); }); document.getElementById('leaderboard-btn').addEventListener('click', () => { renderLeaderboard(); document.getElementById('leaderboard-modal').classList.remove('hidden'); }); document.getElementById('close-leaderboard').addEventListener('click', () => document.getElementById('leaderboard-modal').classList.add('hidden')); document.getElementById('clear-leaderboard').addEventListener('click', () => { localStorage.removeItem('void-survivors-top-five'); renderLeaderboard(); }); document.getElementById('again-btn').addEventListener('click', createRun); document.getElementById('restart-btn').addEventListener('click', createRun); document.getElementById('finish-btn').addEventListener('click', finishRun); document.getElementById('endless-btn').addEventListener('click', continueEndless); document.getElementById('pause-btn').addEventListener('click', togglePause); document.getElementById('god-mode-toggle').addEventListener('change', event => { if (game) game.godMode = event.target.checked; }); document.getElementById('resume-btn').addEventListener('click', togglePause); document.getElementById('quit-btn').addEventListener('click', () => { game.running = false; document.getElementById('pause-modal').classList.add('hidden'); document.getElementById('game-screen').classList.remove('active'); document.getElementById('start-screen').classList.add('active'); });
function setPointer(event) { const rect = canvas.getBoundingClientRect(); pointer.x = event.clientX - rect.left; pointer.y = event.clientY - rect.top; }
canvas.addEventListener('pointerdown', event => { pointer.active = true; setPointer(event); canvas.setPointerCapture(event.pointerId); }); canvas.addEventListener('pointermove', event => { if (pointer.active) setPointer(event); }); canvas.addEventListener('pointerup', () => { pointer.active = false; }); canvas.addEventListener('pointercancel', () => { pointer.active = false; });
